/**
 * TASK: Build a "mute" switch by ADDING and REMOVING a listener.
 *
 * The panel holds a button named "bump", a checkbox named "mute" and a
 * label named "count". The counting listener already exists as the field
 * counterListener, and the constructor registers it on the button.
 *
 * Complete setMuted and isMuted:
 *   setMuted(true)  -- the button must end up with counterListener REMOVED,
 *                      so clicking it changes nothing.
 *   setMuted(false) -- the button must end up with counterListener registered
 *                      EXACTLY ONCE, even when setMuted(false) is called twice
 *                      in a row (a second addActionListener call would make
 *                      every later click count twice).
 *   isMuted()       -- true when the button currently has no action listeners.
 *
 * Example: click, mute, click, unmute, click -> the label reads "2".
 *
 * The checkbox is already wired to call setMuted for you.
 */
import java.awt.event.ActionListener;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JLabel;
import javax.swing.JPanel;

public class MutingCounterPanel extends JPanel {

    private final JButton bump = new JButton("Bump");
    private final JCheckBox mute = new JCheckBox("Mute");
    private final JLabel count = new JLabel("0");
    private int clicks = 0;

    private final ActionListener counterListener = e -> {
        clicks++;
        count.setText(String.valueOf(clicks));
    };

    public MutingCounterPanel() {
        bump.setName("bump");
        mute.setName("mute");
        count.setName("count");
        add(bump);
        add(mute);
        add(count);
        bump.addActionListener(counterListener);
        mute.addActionListener(e -> setMuted(mute.isSelected()));
    }

    public void setMuted(boolean muted) {
        // TODO: when muted is true, remove counterListener from bump
        // TODO: when muted is false, put it back -- but never register it twice
    }

    public boolean isMuted() {
        // TODO: report whether bump currently has no action listeners at all
        return false;
    }
}

