public class MutingCounterPanelTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String textOf(java.awt.Component c) {
        if (c instanceof javax.swing.JLabel) {
            return ((javax.swing.JLabel) c).getText();
        }
        if (c instanceof javax.swing.text.JTextComponent) {
            return ((javax.swing.text.JTextComponent) c).getText();
        }
        return "(missing)";
    }

    public static void main(String[] args) {
        try {
            MutingCounterPanel panel = new MutingCounterPanel();
            javax.swing.JButton bump = (javax.swing.JButton) find(panel, "bump");
            javax.swing.JCheckBox mute = (javax.swing.JCheckBox) find(panel, "mute");
            java.awt.Component label = find(panel, "count");

            check("a fresh panel is not muted", false, panel.isMuted());
            bump.doClick();
            check("one click counts", "1", textOf(label));

            mute.doClick();
            check("isMuted after ticking the box", true, panel.isMuted());
            check("listener removed from bump", 0, bump.getActionListeners().length);
            bump.doClick();
            check("clicks while muted are ignored", "1", textOf(label));

            mute.doClick();
            check("listener restored on unmute", 1, bump.getActionListeners().length);
            bump.doClick();
            check("counting resumes", "2", textOf(label));

            panel.setMuted(false);
            check("unmuting twice does not double-register", 1, bump.getActionListeners().length);
            bump.doClick();
            check("each click still counts once", "3", textOf(label));
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected problem -- " + t);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

