import java.awt.event.ActionListener;
import javax.swing.JButton;
import javax.swing.JCheckBox;
import javax.swing.JLabel;
import javax.swing.JPanel;

public class MutingCounterPanel extends JPanel {

    private final JButton bump = new JButton("Bump");
    private final JCheckBox mute = new JCheckBox("Mute");
    private final JLabel count = new JLabel("0");
    private int clicks = 0;

    private final ActionListener counterListener = e -> {
        clicks++;
        count.setText(String.valueOf(clicks));
    };

    public MutingCounterPanel() {
        bump.setName("bump");
        mute.setName("mute");
        count.setName("count");
        add(bump);
        add(mute);
        add(count);
        bump.addActionListener(counterListener);
        mute.addActionListener(e -> setMuted(mute.isSelected()));
    }

    public void setMuted(boolean muted) {
        if (muted) {
            bump.removeActionListener(counterListener);
        } else if (isMuted()) {
            bump.addActionListener(counterListener);
        }
    }

    public boolean isMuted() {
        return bump.getActionListeners().length == 0;
    }
}
